INSERT INTO userdb.course (id, course_name, category, description, online, schedule_time, duration, instructor, location, highlight_str, max_students, contact_phone) VALUES (1001, '新手骑行入门培训', '新手入门', '适合刚拿驾照的新手，包含基础操作、起步刹车、安全知识、道路规则等内容。包含理论课程和实操训练。', 0, '每周三 19:00-21:00', '2小时', '张教练', '北京市朝阳区训练场', null, 20, '13800138001');
INSERT INTO userdb.course (id, course_name, category, description, online, schedule_time, duration, instructor, location, highlight_str, max_students, contact_phone) VALUES (1002, '进阶骑行技巧提升', '进阶技巧', '适合有一定骑行经验的骑友。包含弯道技巧、紧急避险、高速骑行、雨天骑行等高级技术训练。', 0, '每周六 14:00-17:00', '3小时', '李教练', '封闭场地', null, 15, '13800138002');
INSERT INTO userdb.course (id, course_name, category, description, online, schedule_time, duration, instructor, location, highlight_str, max_students, contact_phone) VALUES (1003, '摩托车日常保养维修', '保养维修', '教你自己动手进行日常保养：换机油、清洗链条、调整刹车、更换火花塞等基础维修技能。', 1, '线上随时学习', '2小时', '王师傅', '线上课程', null, 2, '13111111111');
INSERT INTO userdb.course (id, course_name, category, description, online, schedule_time, duration, instructor, location, highlight_str, max_students, contact_phone) VALUES (1004, '安全骑行意识培训', '安全培训', '防御性驾驶理念、事故案例分析、应急处理技巧、装备选择等安全知识。支持线上学习。', 1, '线上随时学习', '2小时', '赵教练', '线上课程', null, 0, '13800138004');
